typedef enum {READ, WRITE, IDLE} op_e;

bit [3:0] addr;
op_e      op;

covergroup cg @(posedge clk);
  cp_addr: coverpoint addr {
    bins low     = {[0:3]};
    bins mid[]   = {[4:7]};
    bins high[2] = {[8:15]};
  }
  cp_op: coverpoint op;
  x_addr_op: cross cp_addr, cp_op;
endgroup

