class ooo_scoreboard extends uvm_scoreboard;
  `uvm_component_utils(ooo_scoreboard)

  uvm_analysis_imp_req #(txn, ooo_scoreboard) req_imp;
  uvm_analysis_imp_rsp #(txn, ooo_scoreboard) rsp_imp;

  txn expected[bit [3:0]];          // keyed by ID

  function new(string name, uvm_component parent);
    super.new(name, parent);
    req_imp = new("req_imp", this);
    rsp_imp = new("rsp_imp", this);
  endfunction

  function void write_req(txn t);
    if (expected.exists(t.id))
      `uvm_error("SB", $sformatf("ID %0d reused while outstanding", t.id))
    expected[t.id] = predict(t);    // reference model
  endfunction

  function void write_rsp(txn t);
    if (!expected.exists(t.id)) begin
      `uvm_error("SB", $sformatf("Unexpected response, ID %0d", t.id))
      return;
    end
    if (!t.compare(expected[t.id]))
      `uvm_error("SB", $sformatf("Data mismatch, ID %0d", t.id))
    expected.delete(t.id);
  endfunction

  function void check_phase(uvm_phase phase);
    if (expected.size() != 0)
      `uvm_error("SB", $sformatf("%0d responses never arrived", expected.size()))
  endfunction
endclass

