module det1011 (
  input  logic clk, rst_n, x,
  output logic found
);
  typedef enum logic [2:0] {S0, S1, S10, S101, S1011} state_t;
  state_t state, next;

  always_ff @(posedge clk or negedge rst_n)
    if (!rst_n) state <= S0;
    else        state <= next;

  always_comb begin
    next = state;
    unique case (state)
      S0:    if (x) next = S1;    else next = S0;
      S1:    if (x) next = S1;    else next = S10;
      S10:   if (x) next = S101;  else next = S0;
      S101:  if (x) next = S1011; else next = S10;
      S1011: if (x) next = S1;    else next = S10;
    endcase
  end

  assign found = (state == S1011);
endmodule

assign empty = (wr_ptr == rd_ptr);
