assign gray = bin ^ (bin >> 1);

// Gray back to binary: each bit is the XOR of all Gray bits at or above it
always_comb begin
  bin[3] = gray[3];
  for (int i = 2; i >= 0; i--)
    bin[i] = bin[i+1] ^ gray[i];
end
